    private const val ALL_JSON = """{"welcome":[],"profile":[],"about":[{"id":"Qkkn6rZsSHRCYwYBA8fu","owner_id":"t8AFhsy1JQjxdjjmnYLK","header":"Oh Hello there,","text":"My name is Tim Baz. I am a design engineer, who enjoys working on mobile apps at all level - from networking up to user interfaces, whatever's in between. I studied Computer Science in Germany and moved to the United States three and a half years ago.","order":1},{"id":"l3o0xKHjIJXjcQV3gx7X","owner_id":"t8AFhsy1JQjxdjjmnYLK","header":"Where have I been?","text":"After I graduated in Germany, I moved back to Mongolia and started my career as a team lead of a messaging app at a local mobile operator company. As a result, I became familiar with Android. Three years later, I started my business-building Android apps and published two apps on the Google Play store. Then I moved to the United States to join my family.","order":2},{"id":"Bbo0LWOxZE6oiKRKFC2S","owner_id":"t8AFhsy1JQjxdjjmnYLK","header":"Professional Design Engineer","text":"When I came to the US, the idea to become a professional design engineer stuck with me, so I began to study Kotlin and Android Jetpack components. After a year and a half later, I published two Kotlin Android apps on the Google Play store.","order":3},{"id":"rlSn8aPDg6mAtgXyqnln","owner_id":"t8AFhsy1JQjxdjjmnYLK","header":"Current projects","text":"Recently, I have been working on some projects, and one of them is a sign language app dedicated to kids for helping to learn Mongolian and American sign language.","order":4},{"id":"MMhWNOmaPUfowE9vjvSH","owner_id":"t8AFhsy1JQjxdjjmnYLK","header":"Hobby","text":"Other than my passion for building Android apps, I have a strong interest in running and traveling.","order":5},{"id":"ZIjYjq62XNFNB4pdcKLi","owner_id":"t8AFhsy1JQjxdjjmnYLK","header":"what I am looking for","text":"I am open to career opportunities to expand my Android knowledge, and I would love to join any teams and companies that share values in Android development.","order":"6"}],"social":[],"app":[{"id":"bGnIxMB0BmlzM0AFCf7s","title":"Current Version","text":"1.5.2","order":1},{"id":"txARXsQ6BVVAzFgfSYbU","title":"Latest Version","text":"1.5.2","order":2},{"id":"1x1xgTdg49vn5mzqcEwv","title":"Last updated","text":"June 23, 2019","order":3}],"portfolio":[{"id":"YvlbIeO4gwikTqhO3bF8","owner_id":"t8AFhsy1JQjxdjjmnYLK","title":"Portfolio App","sub_title":"Portfolio App 2.0","logo":"https://tumur.me/img/portfolio-app-icon.png","logo_description":"app's logo","cover_image":"https://tumur.me/img/portfolio_screen.jpg","image_description":"User profile screen","info":"Applied number of best practices from the Android community, and I'm thankful to everyone who shared their knowledge and experience through social media and blog posts.","text":"This is the latest version of my portfolio app where I want to share my skills and passion for Android development and it's a result of what I've learned through my learning of Kotlin and Android Jetpack, Material design and Firebase components. The app was written in Kotlin, built with Android Jetpack components and many third-party libraries such as Retrofit, OkHttp, Glide, LeanCanary, Koin, Kotlin Coroutines, etc. The code is available on Github, and it may help others to learn the latest Android development technologies to build fully functional Android apps.","date_from":"2018-11-02T07:00:00.000Z","date_to":"2019-08-07T07:00:00.000Z","order":1,"header":"Android Apps","type":1,"link_to_share":"https://ioco-5c746.web.app/a/","video_url":"https://youtu.be/YjVJyqcv5I8"},{"id":"2LinPN2Mh8oBunXcepf1","owner_id":"t8AFhsy1JQjxdjjmnYLK","title":"Ponda App","sub_title":"Read Key Ideas","logo":"https://tumur.me/img/ponda-app-icon.png","logo_description":"app's logo","cover_image":"https://tumur.me/img/ponda_screen.jpg","image_description":"Home screen","info":"The app is called after \"Giant Panda\" known as a panda bear to awake awareness of the people for distinction of the animals.","text":"Helps people to read key ideas of best-selling books for personal development. The app provides the content in text and audio formats, and it supports accessibility for the visually impaired and blind community.","date_from":"2018-11-01T07:00:00.000Z","date_to":"2019-08-07T07:00:00.000Z","order":2,"header":"Android Apps","type":1,"link_to_share":"https://8io.co/po/","video_url":"https://www.youtube.com/watch?v=NfCFAsJsNp8"},{"id":"iRKgF6SOYc76Xkpgl2WT","owner_id":"t8AFhsy1JQjxdjjmnYLK","title":"Portfolio App 1.0","sub_title":"Portfolio App 1.0","logo":"https://tumur.me/img/resume-icon.png","logo_description":"app logo","cover_image":"https://tumur.me/img/resume_screen.jpg","image_description":"User profile screen","info":"This is a result of what I've learned through learning of Java and standard Android SDK APIs.","text":"Portfolio app 1.0 is a simple Java-Android application where I want to show my skills and passion for Android development, and it was written in Java and built with standard Android SDK APIs and MVC(Model-View-Control) design architecture.","date_from":"2018-05-01T07:00:00.000Z","date_to":"2019-02-03T08:00:00.000Z","order":3,"header":"Android Apps","type":2,"link_to_share":"https://ioco-5c746.web.app/d/","video_url":"https://youtu.be/j56fSGqF7Ho"}],"button":[{"id":"XrbJvWi0ZsFh47rBuH4P","owner_id":"2LinPN2Mh8oBunXcepf1","title":"Play Store","url":"https://play.google.com/store/apps/dev?id=4872099625526337244","type":"google","order":2},{"id":"Yre1sZ7NDf3n9DIXuoRZ","owner_id":"2LinPN2Mh8oBunXcepf1","title":"Github","url":"https://github.com/tumurb/Mongolian-Sign-Language-Dictionary","type":"github","order":1},{"id":"rRsCWnMQSkdPiP7hpvat","owner_id":"46U0IVJRyjAEEWtC5pKH","title":"Website","url":"https://www.unitel.mn/unitel/","type":"web","order":2},{"id":"yFaeif9jjBHJh91N72Tr","owner_id":"46U0IVJRyjAEEWtC5pKH","title":"Statement","url":"https://drive.google.com/open?id=1HfykOAHk7sop-ZkzW93eOs29UQD2yBIs","type":"statement","order":1},{"id":"LdOhL9gy6bDk